namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int MaximumRatePoints = 10;

    public static int PayableTotalCents(int subtotalCents, LoyaltyTier tier)
    {
        var baseRate = tier switch
        {
            LoyaltyTier.Green => 5,
            LoyaltyTier.Gold => 7,
            LoyaltyTier.Platinum => 9,
            _ => throw new ArgumentOutOfRangeException(nameof(tier)),
        };
        var bonus = subtotalCents >= 20_000 ? 3 : subtotalCents >= 5_000 ? 1 : 0;
        var rate = Math.Min(baseRate + bonus, MaximumRatePoints);

        return subtotalCents - (int)((long)subtotalCents * rate / 100);
    }
}
